<?php declare(strict_types=1);
// Retain explicit historical setup links without advertising the old wizard.
if(!array_key_exists('setup',$_GET)&&!array_key_exists('intro_result',$_GET))return;
$dashSetup=$dashState['setup'];$dashError('setup');if($dashSetup!==null&&$dashSetup['groups']): ?>
<details class="dwf-card dashboard-setup" data-dashboard-setup <?= $dashSetup['open']?'open':'' ?>><summary><?= e($dashI('Erste Schritte in der Vereinsverwaltung')) ?></summary><p><?= e($dashI('Einrichtung und optionale Arbeitsabläufe')) ?></p><nav class="dwf-actions" aria-label="<?= e($dashI('Einrichtungsbereiche')) ?>"><?php foreach($dashSetup['groups']as$dashGroupId=>$dashGroup):?><a class="btn btn-outline theme-secondary dwf-button" <?= $dashSetup['selected']===$dashGroupId?'aria-current="page"':'' ?> href="<?= e($dashUrl(['setup'=>$dashGroupId])) ?>"><?= e($dashI($dashGroup['label'])) ?> · <?= e($dashF('{count} nicht erkannt',['count'=>$dashGroup['pending']])) ?></a><?php endforeach ?></nav>
<p><?= e($dashI('Die Anzeige erkennt gespeicherte Einstellungen. Optionale Werkzeuge zählen nicht als unerledigte Pflicht. Nicht benötigte Funktionen können ungenutzt bleiben.')) ?></p>
<?php if($dashSetup['selected']!==null):foreach($dashSetup['groups'][$dashSetup['selected']]['items']as$dashTask):?><article class="dashboard-setup-task"><h3><?= e($dashI($dashTask['label'])) ?></h3><p><?= e($dashI(['done'=>'Gespeicherter Stand erkannt','pending'=>'Noch kein gespeicherter Stand erkannt','optional'=>'Optionaler Einstieg'][$dashTask['state']])) ?></p>
<?php if($dashTask['route']['view']==='dashboard'):?><p><?= e($dashI('Mitglieder und Kontakte stehen in einem eigenen Bereich. Bankkonten und Handkassen werden getrennt geführt. Ein Beleg erzeugt erst dann einen Geldfluss, wenn eine neue Zahlung erfasst wird.')) ?></p><p><?= e($dashI('Website, Newsletter, Social Media und Presse verwenden die für diesen Verein eingerichteten Bereiche. Änderungen folgen dem jeweiligen Veröffentlichungsstatus.')) ?></p>
<?php if($dashSetup['acknowledgement']===null):if(($_GET['intro_result']??null)==='1'):?><p role="status" data-dashboard-intro-status><?= e($dashI('Für diesen Verein ist noch keine gespeicherte Einführungsbestätigung nachgewiesen.')) ?></p><?php endif ?><form method="post" data-dashboard-intro><?= csrf().hidden('action','complete-intro').hidden('dashboard_native','1') ?><button class="btn btn-solid theme-primary dwf-button"><?= e($dashI('Einführung gelesen')) ?></button></form><?php else:$dashAck=$dashSetup['acknowledgement'];?><section data-dashboard-intro-original><h4><?= e($dashI('Erste gespeicherte Einführungsbestätigung')) ?></h4><p><time data-dashboard-intro-time datetime="<?= e($dashAck['completed_at']) ?>"><?= e($dashDate($dashAck['completed_at'],true)) ?></time> · <?= e($dashI('Zeit in Berlin')) ?></p><p class="dashboard-original" data-dashboard-intro-account="<?= e($dashAck['actor_id']) ?>"><?= e($dashF('Bestätigt durch Konto {actor}',['actor'=>$dashAck['actor_id']])) ?></p><p><?= e($dashI('Der damalige Einführungstext wurde nicht gespeichert. Diese Angaben ersetzen keine historischen Textfassungen.')) ?></p></section><?php endif ?>
<p><a class="dwf-button" href="<?= e(url(['view'=>'dashboard','setup'=>'setup','intro_result'=>'1'])) ?>"><?= e($dashI('Einführungsstand dieses Vereins prüfen')) ?></a></p><p><?= e($dashI('Nach einer verlorenen Antwort öffne diesen Prüfzugang in einer neuen Seite. Die Prüfung liest den ersten gespeicherten Stand und bestätigt nichts erneut.')) ?></p>
<?php else:?><a class="btn btn-outline theme-secondary dwf-button" href="<?= e(url($dashTask['route'])) ?>"><?= e($dashI($dashTask['state']==='done'?'Gespeicherten Bereich öffnen':'Bereich öffnen')) ?></a><?php endif ?></article><?php endforeach;endif ?></details><?php endif ?>
